package com.autocare.platform.order;
import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.service.MerchantActor;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import static com.autocare.platform.order.ReservationStore.*;

/** Source policy only. Legacy default scores never become verified calculations here. */
public class AssessmentPolicies {
 public static final String PATH="/api/admin/assessment/policies",RULE="R8B_POLICY_V1";
 private final ReservationStore db;private final OperatorIdentity operators;
 public AssessmentPolicies(ReservationStore db,OperatorIdentity operators){this.db=db;this.operators=operators;}
 private void authorize(OperatorActor a,boolean lock){operators.authorize(a,OperatorIdentity.Permission.ASSESSMENT,lock);}
 private static org.springframework.web.server.ResponseStatusException conflict(){return new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"考核政策、门店或生效月份已变化，请重新读取");}
 private void pageNumber(int p){if(p<1||p>1000000)throw ReservationInput.bad();}
 private Map<String,Object> merchant(long id,boolean lock){return db.one("SELECT id,name,address FROM merchant WHERE id=? AND status=1 AND is_deleted=0"+(lock?" FOR UPDATE":""),id);}
 private Map<String,Object> merchantView(Map<String,Object> r){return Map.of("id",r.get("id"),"name",r.get("name"),"address",Objects.toString(r.get("address"),""));}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM assessment_policy WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 Map<String,Object> view(Map<String,Object> r){var n=new LinkedHashMap<String,Object>();for(String k:List.of("id","merchant_id","acquisition_target","coupon_target","source_note","revision","status","rule_version"))n.put(k,r.get(k));n.put("merchant",db.parse(r.get("merchant_snapshot")));for(String k:List.of("process_requirements","grade_thresholds"))n.put(k,db.parse(r.get(k)));n.put("scope","MERCHANT");n.put("period","BEIJING_MONTH");n.put("timezone","Asia/Shanghai");n.put("weights",Map.of("acquisition",40,"coupon",40,"process",20));n.put("metric_source_version","R8B_FACTS_V1");n.put("formula","TARGET_RATE_AND_PROCESS_COMPLETENESS_V1");for(String k:List.of("valid_from","valid_to","created_at","published_at"))n.put(k,iso(r.get(k)));return n;}
 public Map<String,Object> merchants(OperatorActor a,int p){pageNumber(p);return db.reads.execute(tx->{authorize(a,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM merchant WHERE status=1 AND is_deleted=0",Long.class);return page(db.jdbc.queryForList("SELECT id,name,address FROM merchant WHERE status=1 AND is_deleted=0 ORDER BY id DESC LIMIT 20 OFFSET ?",(p-1)*20L).stream().map(this::merchantView).toList(),count,p,20);});}
 public Map<String,Object> list(OperatorActor a,int p){pageNumber(p);return db.reads.execute(tx->{authorize(a,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM assessment_policy",Long.class);return page(db.jdbc.queryForList("SELECT * FROM assessment_policy ORDER BY id DESC LIMIT 20 OFFSET ?",(p-1)*20L).stream().map(this::view).toList(),count,p,20);});}
 private String hash(JsonNode b){return AuthTokens.sha256(db.json(AssessmentPolicyInput.canonical(b)));}
 public JsonNode create(OperatorActor a,String key,JsonNode b){String normalized=WriteIntegrityService.normalizeKey(key),hash=hash(b);return db.writes.execute(new Actor("operator_account",a.id()),"POST",PATH,key,b,()->authorize(a,true),()->{
  var previous=db.jdbc.queryForList("SELECT id,submission_hash,creation_result FROM assessment_policy WHERE created_by=? AND submission_key=?",a.id(),normalized);
  if(!previous.isEmpty()){var r=previous.get(0);if(!hash.equals(r.get("submission_hash")))throw ReservationInput.bad();var saved=db.parse(r.get("creation_result"));if(!saved.isObject())throw new IllegalStateException("Assessment creation receipt missing");Map<String,Object> data=db.mapper.convertValue(saved,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});return new Change("ASSESSMENT_POLICY_CREATE","assessment_policy",number(r,"id"),Map.of(),Map.of(),data,false);}
  var shop=merchant(b.path("merchant_id").asLong(),true);if(!CouponInput.time(b.get("valid_from")).isAfter(db.now()))throw conflict();long id=db.insert("INSERT INTO assessment_policy(merchant_id,merchant_snapshot,acquisition_target,coupon_target,process_requirements,grade_thresholds,source_note,valid_from,valid_to,created_by,submission_key,submission_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",b.path("merchant_id").asLong(),db.json(merchantView(shop)),b.path("acquisition_target").asInt(),b.path("coupon_target").asInt(),b.get("process_requirements").toString(),b.get("grade_thresholds").toString(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),a.id(),normalized,hash,time(db.now()));var after=view(row(id,true));db.jdbc.update("UPDATE assessment_policy SET creation_result=? WHERE id=?",db.json(after),id);return new Change("ASSESSMENT_POLICY_CREATE","assessment_policy",id,Map.of(),after,after);
 });}
 public JsonNode update(OperatorActor a,long id,String key,JsonNode b){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.writes.execute(new Actor("operator_account",a.id()),"PUT",PATH+"/"+id,key,b,()->authorize(a,true),()->{var shop=merchant(b.path("merchant_id").asLong(),true);var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=b.path("expected_revision").asLong()||!CouponInput.time(b.get("valid_from")).isAfter(db.now()))throw conflict();var before=view(r);db.jdbc.update("UPDATE assessment_policy SET merchant_id=?,merchant_snapshot=?,acquisition_target=?,coupon_target=?,process_requirements=?,grade_thresholds=?,source_note=?,valid_from=?,valid_to=?,revision=revision+1 WHERE id=?",b.path("merchant_id").asLong(),db.json(merchantView(shop)),b.path("acquisition_target").asInt(),b.path("coupon_target").asInt(),b.get("process_requirements").toString(),b.get("grade_thresholds").toString(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),id);var after=view(row(id,true));return new Change("ASSESSMENT_POLICY_UPDATE","assessment_policy",id,before,after,after);});}
 public JsonNode status(OperatorActor a,long id,String key,JsonNode b){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.writes.execute(new Actor("operator_account",a.id()),"PUT",PATH+"/"+id+"/status",key,b,()->authorize(a,true),()->{String target=b.path("status").asText();var first=row(id,false);var shop=target.equals("PUBLISHED")?merchant(number(first,"merchant_id"),true):null;var r=row(id,true);if(number(r,"revision")!=b.path("expected_revision").asLong()||!(target.equals("PUBLISHED")?"DRAFT".equals(r.get("status")):target.equals("STOPPED")&&"PUBLISHED".equals(r.get("status"))))throw conflict();if(shop!=null&&(number(shop,"id")!=number(r,"merchant_id")||!instant(r.get("valid_from")).isAfter(db.now())))throw conflict();var before=view(r);try{db.jdbc.update("UPDATE assessment_policy SET status=?,revision=revision+1,merchant_snapshot=?,published_at=?,stopped_at=? WHERE id=?",target,shop==null?r.get("merchant_snapshot").toString():db.json(merchantView(shop)),target.equals("PUBLISHED")?time(db.now()):r.get("published_at"),target.equals("STOPPED")?time(db.now()):null,id);}catch(org.springframework.dao.DuplicateKeyException e){throw conflict();}var after=view(row(id,true));return new Change("ASSESSMENT_POLICY_STATUS","assessment_policy",id,before,after,after);});}
 public Map<String,Object> current(MerchantActor a){if(!a.manager())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"仅店长可读取本店考核政策");return db.reads.execute(tx->{db.merchant(a,false);var rows=db.jdbc.queryForList("SELECT * FROM assessment_policy WHERE merchant_id=? AND status='PUBLISHED'",a.merchantId());var n=new LinkedHashMap<String,Object>();n.put("state","UNKNOWN");n.put("policy",null);n.put("scoring_available",true);n.put("timezone","Asia/Shanghai");if(rows.size()==1){var r=rows.get(0);var at=db.now();n.put("policy",view(r));n.put("state",instant(r.get("valid_from")).isAfter(at)?"NOT_STARTED":!instant(r.get("valid_to")).isAfter(at)?"EXPIRED":"CONFIGURED");}return n;});}
}
